package main

import (
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/dop251/goja/parser"
	"golang.org/x/net/html"
)

// extractScriptContents uses HTML parser to extract all script tag contents
func extractScriptContents(htmlContent string) []string {
	var scripts []string
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return scripts
	}

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == "script" {
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				if c.Type == html.TextNode {
					scripts = append(scripts, c.Data)
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return scripts
}

// extractDataAttributes extracts data-* attributes from elements with given class
func extractDataAttributes(htmlContent string, className string) map[string]string {
	attrs := make(map[string]string)
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return attrs
	}

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			var hasClass bool
			for _, attr := range n.Attr {
				if attr.Key == "class" && strings.Contains(attr.Val, className) {
					hasClass = true
					break
				}
			}
			if hasClass {
				for _, attr := range n.Attr {
					if strings.HasPrefix(attr.Key, "data-") {
						attrs[attr.Key] = attr.Val
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return attrs
}

// checkForEventHandlers checks if any element has event handler attributes
func checkForEventHandlers(htmlContent string) []string {
	var handlers []string
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return handlers
	}

	eventAttrs := []string{"onclick", "onmouseover", "onmouseout", "onfocus", "onblur", "onerror", "onload", "onchange", "oninput", "onsubmit"}
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			for _, attr := range n.Attr {
				for _, evt := range eventAttrs {
					if strings.ToLower(attr.Key) == evt {
						handlers = append(handlers, attr.Key+"="+attr.Val)
					}
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return handlers
}

// validateJSStructure parses JavaScript and validates it only contains safe constructs
func validateJSStructure(jsCode string) error {
	_, err := parser.ParseFile(nil, "", jsCode, 0)
	return err
}

// checkForDangerousCalls checks if the JS code contains function calls like alert, eval, etc.
func checkForDangerousCalls(jsCode string) bool {
	dangerousFunctions := []string{
		"alert(", "eval(", "Function(", "setTimeout(", "setInterval(",
		"document.write(", "document.writeln(", "innerHTML", "outerHTML",
		"insertAdjacentHTML", "execScript(", "console.log(",
	}
	for _, fn := range dangerousFunctions {
		if strings.Contains(jsCode, fn) {
			return true
		}
	}
	return false
}

