// HTML Encoding Verification Tests
// These tests verify that special characters are properly HTML-encoded in different contexts,
// rather than relying on keyword blacklists (onclick, onerror, etc.)

// countHtmlElements counts the number of specific HTML elements in the response
func countHtmlElements(htmlContent string, tagName string) int {
	count := 0
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return count
	}

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == tagName {
			count++
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return count
}

func TestSecHtmlEncoding_AngleBracketsInUsername(t *testing.T) {
	// Test that < and > in username are properly HTML-encoded
	maliciousUsername := "<script>alert('xss')</script>"
	req := httptest.NewRequest(http.MethodGet, "/dashboard?username="+url.QueryEscape(maliciousUsername)+"&email=test@test.com&phone=123&address=addr", nil)
	w := httptest.NewRecorder()
	UserDashboardHandler(w, req)
	body, _ := io.ReadAll(w.Result().Body)
	bodyStr := string(body)

	// Get baseline script count
	normalReq := httptest.NewRequest(http.MethodGet, "/dashboard?username=johndoe&email=test@test.com&phone=123&address=addr", nil)
	normalW := httptest.NewRecorder()
	UserDashboardHandler(normalW, normalReq)
	normalBody, _ := io.ReadAll(normalW.Result().Body)
	normalScriptCount := countHtmlElements(string(normalBody), "script")
	maliciousScriptCount := countHtmlElements(bodyStr, "script")

	if maliciousScriptCount > normalScriptCount {
		t.Errorf("angle brackets not encoded: %d script elements vs %d baseline", maliciousScriptCount, normalScriptCount)
	}

	// Verify encoding: raw <script> should not appear
	if strings.Contains(bodyStr, "<script>alert") {
		t.Error("angle brackets not encoded: raw <script> tag found in response")
	}
