	// Test that quotes in user data are properly encoded when used in data-* attributes
	maliciousUsername := `johndoe" onclick="alert('xss')" data-evil="`
	req := httptest.NewRequest(http.MethodGet, "/dashboard?username="+url.QueryEscape(maliciousUsername)+"&email=test@test.com&phone=123&address=addr", nil)
	w := httptest.NewRecorder()
	UserDashboardHandler(w, req)
	body, _ := io.ReadAll(w.Result().Body)
	bodyStr := string(body)

	// Parse HTML and check that no onclick was injected via attribute breakout
	doc, err := html.Parse(strings.NewReader(bodyStr))
	if err != nil {
		t.Fatalf("Failed to parse HTML: %v", err)
	}

	var injectedOnclick bool
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			for _, attr := range n.Attr {
				if attr.Key == "onclick" && strings.Contains(attr.Val, "alert") {
					injectedOnclick = true
				}
				// Also check for data-evil attribute which would indicate partial breakout
				if attr.Key == "data-evil" {
					injectedOnclick = true
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)

	if injectedOnclick {
		t.Error("quotes not properly encoded in data attributes: attribute breakout detected")
	}
}

