func TestSecJsEncoding_SpecialCharsInUserConfig(t *testing.T) {
	// Test that special characters are properly escaped in JavaScript string context (window.userConfig)
	testCases := []struct {
		name    string
		payload string
	}{
		{"single_quote", `test'; alert('xss'); '`},
		{"double_quote", `test"; alert("xss"); "`},
		{"backslash_quote", `test\"; alert('xss'); //`},
		{"newline", "test\nalert('xss')"},
		{"carriage_return", "test\ralert('xss')"},
		{"script_close", "</script><script>alert('xss')</script>"},
		{"unicode_escape", `\u003cscript\u003ealert('xss')\u003c/script\u003e`},
	}

	// Get baseline AST
	normalReq := httptest.NewRequest(http.MethodGet, "/dashboard?username=johndoe&email=test@test.com&phone=123&address=addr", nil)
	normalW := httptest.NewRecorder()
	UserDashboardHandler(normalW, normalReq)
	normalBody, _ := io.ReadAll(normalW.Result().Body)
	normalScripts := extractScriptContents(string(normalBody))

	var expectedStatementCount int
	for _, script := range normalScripts {
		if strings.Contains(script, "window.userConfig") {
			ast, err := parser.ParseFile(nil, "", script, 0)
			if err == nil {
				expectedStatementCount = len(ast.Body)
				break
			}
		}
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodGet, "/dashboard?username="+url.QueryEscape(tc.payload)+"&email=test@test.com&phone=123&address=addr", nil)
			w := httptest.NewRecorder()
			UserDashboardHandler(w, req)
			body, _ := io.ReadAll(w.Result().Body)
			scripts := extractScriptContents(string(body))

			for _, script := range scripts {
				if !strings.Contains(script, "window.userConfig") {
					continue
				}
				ast, err := parser.ParseFile(nil, "", script, 0)
				if err != nil {
					t.Errorf("JavaScript should be syntactically valid after encoding: %v", err)
					continue
				}
				if len(ast.Body) > expectedStatementCount {
					t.Errorf("special chars not properly escaped: AST has %d statements, expected %d", len(ast.Body), expectedStatementCount)
				}
			}
		})
	}
}

